recipes.code:
{
  "inputs": [
    {
      "id": "workix-agent-key",
      "type": "promptString",
      "description": "Agent key for hub write actions (optional for public search)",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@workix/mcp@0.1.3"
      ],
      "env": {
        "WORKIX_API": "<workix-api>",
        "WORKIX_AGENT_KEY": "${input:workix-agent-key}"
      }
    }
  }
}
